  "inlineSchema": "// Emish Beauty Spa - Prisma Schema\n// Termux / local default: SQLite (provider = \"sqlite\", DATABASE_URL=\"file:./dev.db\")\n// Production: change provider to \"postgresql\" and set DATABASE_URL to your Postgres URL\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  binaryTargets = [\"native\", \"linux-arm64-openssl-1.1.x\"]\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  CUSTOMER\n  ADMIN\n  STAFF\n}\n\nenum OrderStatus {\n  PENDING\n  PAID\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  CANCELLED\n  REFUNDED\n}\n\nenum PaymentStatus {\n  PENDING\n  COMPLETED\n  FAILED\n  REFUNDED\n}\n\nenum PaymentMethod {\n  MPESA\n  TIGO\n  AIRTEL\n  CARD\n  OTHER\n}\n\nmodel User {\n  id           String   @id @default(uuid())\n  phone        String   @unique\n  email        String?  @unique\n  name         String\n  passwordHash String?\n  role         Role     @default(CUSTOMER)\n  referralCode String   @unique\n  referredById String?\n  referredBy   User?    @relation(\"Referrals\", fields: [referredById], references: [id])\n  referrals    User[]   @relation(\"Referrals\")\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  orders      Order[]\n  commissions Commission[]\n  addresses   Address[]\n  cartItems   CartItem[]\n  bookings    Booking[]\n}\n\nmodel Address {\n  id          String   @id @default(uuid())\n  userId      String\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  label       String? // Home, Office...\n  fullName    String\n  phone       String\n  addressLine String\n  city        String\n  region      String?\n  isDefault   Boolean  @default(false)\n  createdAt   DateTime @default(now())\n}\n\nmodel Category {\n  id          String    @id @default(uuid())\n  slug        String    @unique\n  nameEn      String\n  nameSw      String\n  description String?\n  imageUrl    String?\n  sortOrder   Int       @default(0)\n  isActive    Boolean   @default(true)\n  products    Product[]\n  createdAt   DateTime  @default(now())\n}\n\nmodel Product {\n  id                String   @id @default(uuid())\n  slug              String   @unique\n  nameEn            String\n  nameSw            String\n  descriptionEn     String\n  descriptionSw     String\n  howToUseEn        String?\n  howToUseSw        String?\n  ingredients       String?\n  price             Int // in TZS (cents not needed, whole shillings)\n  compareAtPrice    Int? // original/strikethrough price\n  sku               String?  @unique\n  stock             Int      @default(0)\n  lowStockThreshold Int      @default(5)\n  categoryId        String\n  category          Category @relation(fields: [categoryId], references: [id])\n  images            String // JSON array of image URLs for simplicity\n  badge             String? // Bestseller, New, Sale...\n  rating            Float    @default(0)\n  reviewCount       Int      @default(0)\n  isActive          Boolean  @default(true)\n  isFeatured        Boolean  @default(false)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  orderItems OrderItem[]\n  cartItems  CartItem[]\n}\n\nmodel CartItem {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product  @relation(fields: [productId], references: [id])\n  quantity  Int      @default(1)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, productId])\n}\n\nmodel Order {\n  id          String      @id @default(uuid())\n  orderNumber String      @unique // e.g. NC-20260828-XXXX\n  userId      String?\n  user        User?       @relation(fields: [userId], references: [id])\n  status      OrderStatus @default(PENDING)\n\n  // Customer snapshot (for guest checkout too)\n  customerName    String\n  customerPhone   String\n  customerEmail   String?\n  shippingAddress String\n  shippingCity    String\n  shippingRegion  String?\n  notes           String?\n\n  subtotal         Int\n  shippingFee      Int     @default(0)\n  discount         Int     @default(0)\n  total            Int\n  referralCodeUsed String?\n\n  paymentMethod      PaymentMethod?\n  paymentStatus      PaymentStatus  @default(PENDING)\n  pesapalTrackingId  String?\n  pesapalMerchantRef String?\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  paidAt    DateTime?\n\n  items       OrderItem[]\n  commissions Commission[]\n}\n\nmodel OrderItem {\n  id          String  @id @default(uuid())\n  orderId     String\n  order       Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId   String\n  product     Product @relation(fields: [productId], references: [id])\n  productName String // snapshot\n  quantity    Int\n  unitPrice   Int\n  totalPrice  Int\n}\n\nmodel Commission {\n  id        String    @id @default(uuid())\n  userId    String // the referrer\n  user      User      @relation(fields: [userId], references: [id])\n  orderId   String\n  order     Order     @relation(fields: [orderId], references: [id])\n  amount    Int // in TZS\n  rate      Float // e.g. 0.10 for 10%\n  status    String    @default(\"PENDING\") // PENDING, APPROVED, PAID\n  createdAt DateTime  @default(now())\n  paidAt    DateTime?\n}\n\nmodel Setting {\n  id    String @id @default(uuid())\n  key   String @unique\n  value String\n}\n\nenum BookingStatus {\n  PENDING\n  CONFIRMED\n  COMPLETED\n  CANCELLED\n  NO_SHOW\n}\n\nmodel ServiceCategory {\n  id          String    @id @default(uuid())\n  slug        String    @unique\n  nameEn      String\n  nameSw      String\n  description String?\n  sortOrder   Int       @default(0)\n  isActive    Boolean   @default(true)\n  services    Service[]\n  createdAt   DateTime  @default(now())\n}\n\nmodel Service {\n  id              String          @id @default(uuid())\n  slug            String          @unique\n  nameEn          String\n  nameSw          String\n  descriptionEn   String\n  descriptionSw   String\n  durationMinutes Int             @default(60)\n  price           Int\n  compareAtPrice  Int?\n  imageUrl        String?\n  categoryId      String\n  category        ServiceCategory @relation(fields: [categoryId], references: [id])\n  isActive        Boolean         @default(true)\n  isFeatured      Boolean         @default(false)\n  sortOrder       Int             @default(0)\n  createdAt       DateTime        @default(now())\n  updatedAt       DateTime        @updatedAt\n  bookings        Booking[]\n}\n\nmodel Booking {\n  id              String        @id @default(uuid())\n  bookingNumber   String        @unique\n  serviceId       String\n  service         Service       @relation(fields: [serviceId], references: [id])\n  userId          String?\n  user            User?         @relation(fields: [userId], references: [id])\n  customerName    String\n  customerPhone   String\n  customerEmail   String?\n  scheduledAt     DateTime\n  durationMinutes Int\n  status          BookingStatus @default(PENDING)\n  notes           String?\n  price           Int\n  paymentStatus   PaymentStatus @default(PENDING)\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n}\n",
